function drawS3Shapes(system, THREE, G) {
  let R = system._s3Shapes;
  if (!R && !system.list.some(p => p.s3Shape && !(p.delay > 0) && p.owner?.color))
    return { body: 0, slashH: 0, slashV: 0, shell: 0, core: 0, sparkles: 0, sheets: 0, drills: 0 };
  if (!R) R = system._s3Shapes = createRenderer(THREE, system.scene);
  if (!system.list.length && !R.sheets.bursts.length && !R.sheets.drills.length) {
    for (const mesh of [R.body, R.slashH, R.slashV, R.shell, R.core]) { mesh.count = 0; mesh.visible = false; }
    if (R.wetSlashV) { R.wetSlashV.count = 0; R.wetSlashV.visible = false; }
    R.sparks.visible = false; R.sparks.userData.count = 0; R.sparks.geometry.setDrawRange(0, 0);
    R.sheets.mesh.count = R.sheets.drillMesh.count = 0;
    R.sheets.mesh.visible = R.sheets.drillMesh.visible = false;
    return { body: 0, slashH: 0, slashV: 0, shell: 0, core: 0, sparkles: 0, sheets: 0, drills: 0 };
  }
  const { body, bodyData, slashH, slashV, shell, core, sparkPos, sparkSize, m, q, q2, s, v, f, x, y, basis, Z, UP } = R;
  const bd = bodyData.array, cam = G?.camera?.position;
  let nb = 0, nh = 0, nv = 0, nw = 0, ns = 0, nc = 0, nk = 0;
  for (const p of system.list) {
    const kind = p.s3Shape;
    if (!kind || p.delay > 0 || !p.owner?.color) continue;
    const sp = direction(p, f);
    const color = p.owner.color;
    if (FIRE_INK[kind] && p.s3FireSeed !== p.seed) fireInk(R, p, kind, f, G, system);
    if (kind === 'machine' && p.vis > 0) {
      // the round itself: a spinning twisted membrane, never drawn behind the muzzle
      const travel = p.start ? p.start.distanceTo(p.pos) : MACHINE_DRILL.length;
      R.sheets.drill(p.pos, f, color, p.seed || 0, (Number.isFinite(G?.time) ? G.time : 0), Math.min(MACHINE_DRILL.length, travel));
    }
    if (kind === 'shot' || kind === 'pellet' || kind === 'arrow') {
      if (nb >= MAX_BODY) continue;
      const b = bodyParams(p, kind, sp, R.bodyScratch||=( {} ));
      if (!(b.R > 0)) continue;
      q.setFromUnitVectors(Z, f);
      // roll the cross-section with the seed so torn tails differ per round
      q2.setFromAxisAngle(Z, (p.seed || 0) * 6.2832); q.multiply(q2);
      m.compose(p.pos, q, s.setScalar(b.R));
      body.setMatrixAt(nb, m); setTrackedInstanceColor(body, nb, color);
      const o = nb * 4; bd[o] = b.L; bd[o + 1] = b.kind; bd[o + 2] = b.rag; bd[o + 3] = p.seed || 0;
      nb++;
    } else if (kind === 'slash-h' || kind === 'slash-v') {
      const wetWave = splatanaWetWave(p, kind);
      if ((kind === 'slash-h' ? nh : nv + nw) >= MAX_SLASH) continue;
      const mesh = wetWave ? (R.wetSlashV ||= createWetSlash(THREE, system.scene)) : kind === 'slash-h' ? slashH : slashV;
      const n = wetWave ? nw : kind === 'slash-h' ? nh : nv;
      // forward = travel; span horizontal (H) or vertical (V)
      x.crossVectors(UP, f); if (x.lengthSq() < 1e-6) x.set(1, 0, 0); x.normalize();
      y.crossVectors(f, x).normalize();
      if (splatanaHorizontalSweep(p, kind)) basis.makeBasis(x, y, f); else basis.makeBasis(y, x.negate(), f);
      q.setFromRotationMatrix(basis);
      const frames = p.age * 60, lifeFrames = Math.max(1, (p.life || 0.1) * 60);
      const born = 0.55 + 0.45 * smooth(0, 3, frames), late = smooth(lifeFrames * 0.7, lifeFrames, frames);
      s.set(born * (1 - 0.15 * late), born * (1 - 0.6 * late), born * (1 - 0.35 * late));
      m.compose(p.pos, q, s);
      mesh.setMatrixAt(n, m); setTrackedInstanceColor(mesh, n, color);
      if (wetWave) nw++; else if (kind === 'slash-h') nh++; else nv++;
      // Preserve two render instances per physical projectile. The wet peel is
      // an unequal rolled lobe, not another near-identical full-height blade.
      if ((kind === 'slash-h' ? nh : nv + nw) < MAX_SLASH) {
        v.copy(p.pos).addScaledVector(f, -0.28 - 0.1 * born);
        q2.setFromAxisAngle(Z, ((p.seed || 0) - 0.5) * 0.35); q.multiply(q2);
        if (wetWave) {
          // Stay inside the previous combined two-slab envelope. Offset along
          // the existing span basis (vertical here), without moving the shot.
          v.addScaledVector(y, -0.18 * born);
          s.set(s.x * 0.58, s.y * 0.9, s.z * 0.72);
        } else s.multiplyScalar(0.82);
        m.compose(v, q, s);
        const peel = wetWave ? nw : kind === 'slash-h' ? nh : nv;
        mesh.setMatrixAt(peel, m); mesh.setColorAt(peel, color);
        if (wetWave) nw++; else if (kind === 'slash-h') nh++; else nv++;
      }
    } else if (kind === 'bubble') {
      const r = drawRadius(p);
      if (ns < MAX_SHELL && r > 0) {
        m.compose(p.pos, q.identity(), s.setScalar(r));
        shell.setMatrixAt(ns, m); setTrackedInstanceColor(shell, ns, color); ns++;
      }
      // round ink ball floating inside the clear film
      if (nc < MAX_CORE && r > 0) {
        m.compose(p.pos, q.identity(), s.setScalar(r * S3_SHAPE.bubble.core));
        core.setMatrixAt(nc, m); setTrackedInstanceColor(core, nc, color); nc++;
      }
      // tiny empty bubbles drifting behind a young shot (calibration: 0.6 s)
      const fade = 1 - smooth(0.25, 0.6, p.age);
      if (fade > 0 && p.start && ns < MAX_SHELL) {
      const bubbleTravel = p.start.distanceTo(p.pos);
      for (let i = 0; i < S3_SHAPE.bubble.trailing && ns < MAX_SHELL; i++) {
        const seed = (p.seed || 0) * 13.1 + i * 7.3;
        const back = (0.35 + 0.45 * i) * r + 0.2;
        if (back > bubbleTravel) break;
        v.copy(p.pos).addScaledVector(f, -back);
        v.x += (hash(seed, 1) - 0.5) * r; v.y += (hash(seed, 2) - 0.3) * r * 0.8 + p.age * 0.3; v.z += (hash(seed, 3) - 0.5) * r;
        m.compose(v, q.identity(), s.setScalar(r * (0.1 + 0.1 * hash(seed, 4)) * fade));
        shell.setMatrixAt(ns, m); setTrackedInstanceColor(shell, ns, color); ns++;
      }
      }
    } else if (kind === 'explosher') {
      if (cam && cam.distanceToSquared(p.pos) > 3600) continue;
      const n = S3_SHAPE.explosher.sparkles, rad = S3_SHAPE.explosher.radius;
      const normalizedSeed = p.seed || 0;
      let coefficients = R.sparkleCoefficients.get(p);
      if (!coefficients || !Object.is(coefficients.seed, normalizedSeed)) {
        const rows = [];
        for (let i = 0; i < n; i++) {
          const seed = normalizedSeed * 91.7 + i * 3.17;
          const a = hash(seed, 1) * 6.2832, y = 2 * hash(seed, 2) - 1, ring = Math.sqrt(Math.max(0, 1 - y * y));
          rows.push({ seed, x: ring * Math.cos(a), y, z: ring * Math.sin(a), rate: 1.8 + hash(seed, 5), phase: hash(seed, 6), d: rad * (0.9 + 0.8 * hash(seed, 3)), fall: 0.35 + 0.3 * hash(seed, 7), size: hash(seed, 8) });
        }
        coefficients = { seed: normalizedSeed, rows, harmonicFrames: 0 }; R.sparkleCoefficients.set(p, coefficients);
      }
      // Short-lived/capacity-clipped rounds keep the original expression. For
      // ordinary seed/age ranges, share its age phase after two visible frames.
      // A conservative rounding guard below retains the exact Float32 output.
      const agePhase = p.age * 30;
      const harmonic = Number.isFinite(normalizedSeed) && Math.abs(normalizedSeed) <= 1 &&
        Number.isFinite(agePhase) && agePhase >= 0 && agePhase <= 1800 && MAX_SPARK - nk >= 4 &&
        ++coefficients.harmonicFrames > 2;
      const ageSin = harmonic ? Math.sin(agePhase) : 0, ageCos = harmonic ? Math.cos(agePhase) : 0;
      for (let i = 0; i < n && nk < MAX_SPARK; i++) {
        const c = coefficients.rows[i], seed = c.seed;
        // Presentation calibration, not recovered effect data: a tight uneven
        // glitter cloud sheds short trailing/falling flecks. Do not orbit an
        // expanding spherical halo around the projectile. All 28 points still
        // use the existing batch; simulation and gameplay droplets are untouched.
        const phase = fract(p.age * c.rate + c.phase);
        const shed = Math.min(p.age * 3, phase);
        v.set(c.x, c.y, c.z).multiplyScalar(c.d);
        v.addScaledVector(f, -shed * 0.55 * Math.min(1, sp * 0.05));
        v.y -= shed * shed * c.fall;
        v.add(p.pos);
        sparkPos.array[nk * 3] = v.x; sparkPos.array[nk * 3 + 1] = v.y; sparkPos.array[nk * 3 + 2] = v.z;
        if (harmonic && c.phaseSin === undefined) { c.phaseSin = Math.sin(seed * 10); c.phaseCos = Math.cos(seed * 10); }
        let tw = 0.5 + 0.5 * (harmonic ? ageSin * c.phaseCos + ageCos * c.phaseSin : Math.sin(agePhase + seed * 10));
        let size = (0.04 + 0.07 * tw * c.size) * (1 - 0.6 * shed);
        // Leave ample margin for the bounded angles' different rounding.
        // Near a Float32 midpoint, use the original sin.
        if (harmonic && Math.fround(size - 1e-11) !== Math.fround(size + 1e-11)) {
          tw = 0.5 + 0.5 * Math.sin(agePhase + seed * 10);
          size = (0.04 + 0.07 * tw * c.size) * (1 - 0.6 * shed);
        }
        sparkSize.array[nk] = size;
        nk++;
      }
    }
  }
  bodyData.clearUpdateRanges(); bodyData.addUpdateRange(0, nb * 4); bodyData.needsUpdate = nb > 0;
  upload(body, nb); upload(slashH, nh); upload(slashV, nv); upload(shell, ns); upload(core, nc);
  if (R.wetSlashV) upload(R.wetSlashV, nw);
  // SWEPs MuzzleSplash renders at the muzzle attachment every frame
  for (const b of R.sheets.bursts) if (b.owner?.character?.getMuzzle && b.owner.pos) {
    system._muzzle(b.owner, R.v2);
    if (R.v2.distanceToSquared(b.at) < 4) b.at.copy(R.v2);
    if (b.owner.aimDir?.lengthSq?.() > 1e-6) b.dir.copy(b.owner.aimDir).normalize();
  }
  const ink = R.sheets.draw(Number.isFinite(G?.time) ? G.time : 0, cam);
  R.sparks.visible = nk > 0; R.sparks.userData.count = nk; R.sparks.geometry.setDrawRange(0, nk);
  if (nk) {
    sparkPos.clearUpdateRanges(); sparkPos.addUpdateRange(0, nk * 3); sparkPos.needsUpdate = true;
    sparkSize.clearUpdateRanges(); sparkSize.addUpdateRange(0, nk); sparkSize.needsUpdate = true;
  }
  return { body: nb, slashH: nh, slashV: nv + nw, shell: ns, core: nc, sparkles: nk, sheets: ink.sheets, drills: ink.drills };
}

